<script setup lang="ts">
import { ref, reactive, onMounted } from 'vue'
import { useRouter } from 'vue-router'
import { useUserStore } from '@/store/user'
import { showToast, showConfirmDialog } from 'vant'
import { useTimeUtils } from '@/utils/time'

// 路由和状态管理
const router = useRouter()
const userStore = useUserStore()
const userTime = useTimeUtils();
const num = ref(3)
const tits = ref('信用资料')
const yxShow = ref(false)
const lotName = ref('')
const itens = ref('')
const isA = ref(false)
const isB = ref(false)
const isC = ref(false)
const isD = ref(false)
const waterList = ref([])
const userInfo = ref('')
const useful = ref('')
const imgShow =ref(false)
const imId = ref('')
const active = ref('')
const lotList = ref([])
const zdmxShow = ref(false)
const gogtype = ref("")
const ewm = ref("")
const showewm = ref(false)
const codes = ref("")
const jqsmt = ref("")
const tsmx = ref('')
const type = ref({
	1:"A",
	2:"B",
	3:"C",
	4:"D"
})
const jytype = ref(1)
// 初始化组件
onMounted(() => {
    userInfo.value = userTime.safeJSONParse(localStorage.getItem('userInfo'));
    const uus = localStorage.getItem('auuids')
    if(userInfo.value.isInit==2&&uus){
		getUserwin();
    }
})
const setType = (num) =>{
	jytype.value = num;
	if(num==2){
      getGoogle();
	}
}
// Methods
const jqsm = (num) => {
  jqsmt.value = num
  showewm.value = !showewm.value
}

const delMyao = async () => {
  try {
    const res = await userStore.delGoogle(userInfo.value.id)
	showToast({
        title: '解绑成功!',
        icon: 'success',
        className: 'custom-toast',
        duration: 1000  // 自定义显示时间
    });
    if (res.code == 200) {
      getGoogle()
    }
  } catch (error) {
    console.error(error)
  }
}

const getGoogle = async () => {
  try {
    const res = await userStore.getGoogleSecret()
    gogtype.value = res.data
    if (gogtype.value) {
      genQrCode()
    }
  } catch (error) {
    console.error(error)
  }
}

const genQrCode = async () => {
  try {
    const res = await userStore.getQrCode(gogtype.value)
    ewm.value = res.data;
  } catch (error) {
    console.error(error)
  }
}

const subMyao = async () => {
  if (!codes.value) {
	showToast({
        title: '二次验证不能为空!',
        icon: 'success',
        className: 'custom-toast',
        duration: 1000  // 自定义显示时间
    });
    return
  }

  try {
    gogtype.value.code = codes.value
    const res = await userStore.binGoogle(gogtype.value)
	showToast({
        title: '绑定成功!',
        icon: 'success',
        className: 'custom-toast',
        duration: 1000  // 自定义显示时间
    });
    getGoogle()
  } catch (error) {
    console.error(error)
  }
}
    
const getAvatarImage = (ids) => {
    const tn = ids&&ids>0&&ids<31?ids:1;
    return new URL(`../../assets/images/avatar/au_${tn}.png`, import.meta.url).href
}
// 可用额度
const getUserwin = async() =>{
	try {
		let res = await userStore.getslotry();
		useful.value = res.data.toDayWin;
		lotList.value= res.data.lotterys;
		active.value = lotList.value?lotList.value[0].id:'';
	    lotName.value = lotList.value?lotList.value[0].name:''
		getUs();
	} catch (error) {
		console.log('退出登录失败')
	}
}
const getUs = async() =>{
    try {
		let res = await userStore.personaList();
		let str1 = res.data;
		if (str1.handicap&&str1.handicap.search(",") != -1) {
			str1.handicapList = str1.handicap.split(",");
		}else{
			str1.handicapList = [];
		}
		userInfo.value = str1;
		imId.value = userInfo.value.picId;
		localStorage.setItem("userInfo", JSON.stringify(res.data));
		isA.value = false;
		isB.value = false;
		isC.value = false;
		isD.value = false;
		let str = '';
		userInfo.value.handicapList.forEach(item=> {
			str +=type.value[item]+',';
			if (item==1) {
				isA.value = true
			}
			if (item==2) {
				isB.value = true
			}
			if (item==3) {
				isC.value = true
			}
			if (item==4) {
				isD.value = true
			}
		});
		userInfo.value.handicaps = str.substring(0,str.length-1);
		getwater();
	} catch (error) {
		console.log('退出登录失败')
	}
}
const tsTab = (item) =>{
   tsmx.value = item;
   zdmxShow.value = true;
}
const bbsCancel = () =>{
	zdmxShow.value = false;
}
const imgTab = () =>{
    imgShow.value = true;
}
const imgCancel = () =>{
    imgShow.value = false;
}
const seImg = (num) =>{
	imId.value = num;
}
const imgsubs = async() =>{
	try {
		let res = await userStore.editPicId(imId.value);
		imgShow.value = false;
		getUs();
	} catch (error) {
		console.log('退出登录失败')
	}
}
const yxsTab = (num) =>{
	yxShow.value = !yxShow.value;
}
const onConfirm = (item) =>{
	onCancel();
	active.value = item.id;
	lotName.value = item.name;
	getwater();
}
const onCancel = () =>{
	yxShow.value = false;
}
const getwater = async() =>{
	try {
		if(active.value){
          let res = await userStore.getLoadBreak(userInfo.value.id,active.value);
		  waterList.value = res.data;
		}
	} catch (error) {
		console.log('退出登录失败')
	}
}
</script>

